/**
 * Finding the right YouTube video for a song. The ranking rules are plain
 * functions (checked in youtube.test.ts); `searchVideos` is the only part
 * that talks to YouTube.
 *
 * A search costs 100 of the day's 10,000 free units (about 100 searches), so
 * it only runs when you open "Choose a video", and the choice is saved.
 */

export type VideoWarning = "lyrics" | "version" | "length";

export interface VideoCandidate {
  videoId: string;
  title: string;
  channel: string;
  thumbnail: string | null;
  durationMs: number;
  /** An auto-generated upload (cover picture only, clean title): the best kind. */
  topic: boolean;
  warning: VideoWarning | null;
}

/** Words that mean the video shows the lyrics on screen. */
const LYRICS_VIDEO = /\b(lyrics?|lyric video|karaoke|sing[- ]?along|letras?|con letra)\b/i;
/** Other versions of a song that won't match its lyrics' timing. */
const OTHER_VERSION =
  /\b(live|en vivo|cover|remix|instrumental|acoustic|sped up|slowed|nightcore|8d|reverb|reaction)\b/i;

/** A gap this big between the video and the song's length means a different version. */
const LENGTH_WARN_MS = 20_000;

export function decodeEntities(text: string): string {
  return text
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)));
}

/** A song's title without the extras that only get in the way of a search. */
export function cleanSongTitle(title: string): string {
  return title
    .replace(
      /\s*[([][^)\]]*\b(feat|ft|with|remaster(ed)?|version|edit|mix|live|mono|stereo|deluxe|from)\b[^)\]]*[)\]]/gi,
      ""
    )
    .replace(/\s+-\s+.*\b(remaster(ed)?|version|edit|mix|mono|stereo)\b.*$/i, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

export function searchQuery(title: string, primaryArtist: string): string {
  return `${primaryArtist} ${cleanSongTitle(title)}`.trim();
}

/** "PT3M33S" → milliseconds. */
export function parseDuration(iso: string): number {
  const m = /^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(iso);
  if (!m) return 0;
  return ((Number(m[1] ?? 0) * 60 + Number(m[2] ?? 0)) * 60 + Number(m[3] ?? 0)) * 1000;
}

export function looksLikeLyricsVideo(videoTitle: string): boolean {
  return LYRICS_VIDEO.test(videoTitle);
}

/** A different version of the song, unless the song's own title says so too. */
export function looksLikeOtherVersion(videoTitle: string, songTitle: string): boolean {
  const found = OTHER_VERSION.exec(videoTitle);
  return Boolean(found) && !new RegExp(`\\b${found![0]}\\b`, "i").test(songTitle);
}

/** YouTube's own artist channels ("Name - Topic") and "Provided to YouTube by" uploads. */
export function isAutoGenerated(channel: string, description: string): boolean {
  return /\s-\s+Topic$/i.test(channel) || /^Provided to YouTube by/i.test(description.trim());
}

export function warningFor(
  video: { title: string; channel?: string; durationMs: number },
  song: { title: string; durationMs: number }
): VideoWarning | null {
  // Lyrics channels ("Amazing Lyrics") often leave the word out of the title.
  if (looksLikeLyricsVideo(`${video.title} ${video.channel ?? ""}`)) return "lyrics";
  if (looksLikeOtherVersion(video.title, song.title)) return "version";
  if (video.durationMs > 0 && Math.abs(video.durationMs - song.durationMs) > LENGTH_WARN_MS) {
    return "length";
  }
  return null;
}

function score(c: VideoCandidate, songDurationMs: number): number {
  let points = c.topic ? 3 : 0;
  if (c.warning === "lyrics") points -= 6;
  else if (c.warning === "version") points -= 4;
  else if (c.warning === "length") points -= 2;
  const gap = Math.abs(c.durationMs - songDurationMs);
  if (gap <= 3_000) points += 2;
  else if (gap <= 10_000) points += 1;
  return points;
}

/** Best first. Ties keep YouTube's own order (the sort is stable). */
export function rankCandidates(
  candidates: VideoCandidate[],
  song: { durationMs: number }
): VideoCandidate[] {
  return [...candidates].sort((a, b) => score(b, song.durationMs) - score(a, song.durationMs));
}

export type YouTubeFailure = "no_key" | "quota" | "failed";

export class YouTubeError extends Error {
  code: YouTubeFailure;
  constructor(code: YouTubeFailure) {
    super(`YouTube: ${code}`);
    this.code = code;
  }
}

const API = "https://www.googleapis.com/youtube/v3";

async function call(path: string, params: Record<string, string>): Promise<unknown> {
  const key = process.env.YOUTUBE_API_KEY;
  if (!key) throw new YouTubeError("no_key");
  let res: Response;
  try {
    res = await fetch(`${API}/${path}?${new URLSearchParams({ ...params, key })}`, {
      cache: "no-store",
    });
  } catch {
    throw new YouTubeError("failed");
  }
  if (res.ok) return res.json();
  const body = await res.json().catch(() => null);
  const reason = body?.error?.errors?.[0]?.reason;
  console.error(`[youtube] ${path} answered ${res.status} (${reason ?? "no reason"})`);
  throw new YouTubeError(reason === "quotaExceeded" || reason === "rateLimitExceeded" ? "quota" : "failed");
}

interface SearchItem {
  id?: { videoId?: string };
  snippet?: {
    title?: string;
    channelTitle?: string;
    description?: string;
    thumbnails?: { medium?: { url?: string }; default?: { url?: string } };
  };
}

/** The best three videos for a song, best first, each with a warning if it looks wrong. */
export async function searchVideos(song: {
  title: string;
  primaryArtist: string;
  durationMs: number;
}): Promise<VideoCandidate[]> {
  const found = (await call("search", {
    part: "snippet",
    type: "video",
    videoEmbeddable: "true",
    videoSyndicated: "true",
    videoCategoryId: "10", // Music
    maxResults: "10",
    q: searchQuery(song.title, song.primaryArtist),
  })) as { items?: SearchItem[] };

  const items = (found.items ?? []).filter((i) => i.id?.videoId && i.snippet);
  if (items.length === 0) return [];

  const details = (await call("videos", {
    part: "contentDetails",
    id: items.map((i) => i.id!.videoId!).join(","),
  })) as { items?: { id: string; contentDetails?: { duration?: string } }[] };
  const lengths = new Map(
    (details.items ?? []).map((d) => [d.id, parseDuration(d.contentDetails?.duration ?? "")])
  );

  const candidates = items.map((i): VideoCandidate => {
    const title = decodeEntities(i.snippet!.title ?? "");
    const channel = decodeEntities(i.snippet!.channelTitle ?? "");
    const durationMs = lengths.get(i.id!.videoId!) ?? 0;
    return {
      videoId: i.id!.videoId!,
      title,
      channel,
      thumbnail: i.snippet!.thumbnails?.medium?.url ?? i.snippet!.thumbnails?.default?.url ?? null,
      durationMs,
      topic: isAutoGenerated(channel, i.snippet!.description ?? ""),
      warning: warningFor({ title, channel, durationMs }, song),
    };
  });
  return rankCandidates(candidates, song).slice(0, 3);
}
